<p class="audience-notice"><strong>Mailchimp history</strong> · Imported campaign summaries, kept separate from MessageMonkey delivery records. Lifetime opens and clicks are grouped by the campaign’s original send date, using the export’s recorded bot filtering. The all-reports export can include bot or Apple MPP opens that Mailchimp’s filtered cards hide. Native bot and current-segment filters do not reclassify these totals. Importing history never creates send jobs or changes subscriptions.</p>
<?php include __DIR__.'/analytics-filters.php'; ?>
<form method="get" class="analytics-comparison-control"><?php audienceInputs(array_diff_key($reportQuery,['source_audience'=>true])); ?><label>Original Mailchimp audience<select name="source_audience" data-analytics-submit><option value="">All original audiences</option><?php foreach($overview['source_audiences']as$sourceOption): ?><option value="<?= $h($sourceOption['name']) ?>"<?= $window['source_audience']===$sourceOption['name']?' selected':'' ?>><?= $h($sourceOption['name']) ?> (<?= number_format((int)$sourceOption['campaigns']) ?>)</option><?php endforeach; ?></select></label><noscript><button>Apply</button></noscript></form>
<section class="analytics-card"><header><h2>Historical email performance</h2><a href="<?= $h($reportLink(['download'=>'csv'])) ?>">Export daily CSV</a></header>
<dl class="analytics-metrics"><?php foreach(['accepted'=>'Total sends','delivery_rate'=>'Delivery rate','open_rate'=>'Open rate','click_rate'=>'Click rate','clicks_per_open'=>'Clicks per unique opens','unsubscribe_rate'=>'Unsubscribed rate']as$key=>$label): ?><div><dt><?= $h($label) ?></dt><dd><?= $h($key==='accepted'?number_format($totals[$key]):$rate($totals[$key])) ?></dd><small><?= audienceAnalyticsTrend($totals[$key],$previous[$key],$key,$window['compare']!=='none') ?></small></div><?php endforeach; ?></dl>
