<?php $max=max(1,...array_column($overview['daily'],'accepted'));$step=860/max(1,count($overview['daily'])); ?>
<div class="analytics-plot"><svg viewBox="0 0 1000 280" role="img" aria-label="Mailchimp reported sends by original UTC campaign day"><line class="analytics-grid-line" x1="70" x2="950" y1="235" y2="235"/><?php foreach(array_values($overview['daily'])as$i=>$values):$height=200*$values['accepted']/$max; ?><rect x="<?= 80+$i*$step ?>" y="<?= 235-$height ?>" width="<?= max(1,$step-1) ?>" height="<?= $height ?>"><title><?= $h(array_keys($overview['daily'])[$i].' UTC: '.$values['accepted'].' reported sends') ?></title></rect><?php endforeach; ?><text x="70" y="260"><?= $h($window['start']) ?></text><text x="950" y="260" text-anchor="end"><?= $h($window['end']) ?></text></svg></div><p class="analytics-explanation">Mailchimp reported sends by original campaign day, UTC</p>
<details><summary>Daily campaign cohort data</summary><div class="analytics-table-scroll"><table class="data-table"><thead><tr><th>UTC send day</th><th>Sends</th><th>Unique opens</th><th>Unique clickers</th></tr></thead><tbody><?php foreach($overview['daily']as$day=>$values):if(!$values['accepted'])continue; ?><tr><td><?= $h($day) ?></td><td><?= number_format($values['accepted']) ?></td><td><?= number_format($values['opens']) ?></td><td><?= number_format($values['clicks']) ?></td></tr><?php endforeach; ?></tbody></table></div></details>
</section>
<section class="analytics-card"><h2>Imported campaigns</h2><p><?= number_format((int)$summary['campaigns']) ?> retained campaigns across all original audiences<?php if($summary['first_sent']): ?> · <?= $h(substr($summary['first_sent'],0,10).' to '.substr($summary['last_sent'],0,10)) ?> UTC<?php endif; ?></p>
<div class="analytics-table-scroll"><table class="data-table"><thead><tr><th>Campaign</th><th>Original send UTC</th><th>Recipients</th><th>Open rate</th><th>Click rate</th><th>Source</th></tr></thead><tbody>
<?php foreach($overview['campaigns']as$row):$metrics=audienceMailchimpTotals([$row]); ?><tr><td><strong><?= $h($row['name']) ?></strong><details><summary>Source and totals</summary><p>Original audience: <?= $h($row['provenance']['source_audience']??'Not included in CSV') ?></p><p>Mailchimp · <?= $h($row['provenance']['source_timezone']) ?> · <?= $h($row['provenance']['source_local_time']) ?></p><p><?= $h($row['provenance']['identity']) ?> · Filter: <?= $h($row['provenance']['bot_filter']) ?></p><p><?= number_format($metrics['opens']) ?> unique opens · <?= number_format($metrics['total_opens']) ?> total opens · <?= number_format($metrics['clicks']) ?> unique clickers · <?= number_format($metrics['total_clicks']) ?> total clicks · <?= number_format($metrics['unsubscribed']) ?> unsubscribes</p><p>Imported <?= $h($row['imported_at']) ?> UTC · <?= $h($row['source_filename']) ?></p><p>Bundle SHA-256: <code><?= $h($row['bundle_sha256']) ?></code></p></details></td><td><?= $h($row['sent_at']) ?></td><td><?= number_format($metrics['accepted']) ?></td><td><?= $h($rate($metrics['open_rate'])) ?></td><td><?= $h($rate($metrics['click_rate'])) ?></td><td>Mailchimp history</td></tr><?php endforeach; ?>
